import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { fetchFriendRequests, fetchFriends, acceptFriendRequest, rejectFriendRequest, removeFriend } from '../api';
import './FriendRequests.css';

const FriendRequests = () => {
  const [friendRequests, setFriendRequests] = useState([]);
  const [friends, setFriends] = useState([]);
  const [loading, setLoading] = useState(true);
  const [activeTab, setActiveTab] = useState('requests');
  const [notification, setNotification] = useState(null);
  const navigate = useNavigate();

  useEffect(() => {
    const loadData = async () => {
      try {
        // For now, these might return mock data since backend endpoints aren't fully implemented
        const [requestsData, friendsData] = await Promise.all([
          fetchFriendRequests(),
          fetchFriends()
        ]);

        setFriendRequests(requestsData || []);
        setFriends(friendsData || []);
        setLoading(false);
      } catch (error) {
        console.error("Error loading friend data:", error);
        setLoading(false);
      }
    };

    loadData();
  }, []);

  const handleAccept = async (fromUserId) => {
    try {
      const response = await acceptFriendRequest(fromUserId);
      if (response.status === "Success") {
        // Find the accepted request
        const acceptedRequest = friendRequests.find(
          req => req.from.id === fromUserId
        );

        // Update the friend requests list
        setFriendRequests(prevRequests => 
          prevRequests.filter(request => request.from.id !== fromUserId)
        );

        // Add to friends list if request found
        if (acceptedRequest) {
          setFriends(prevFriends => [...prevFriends, acceptedRequest.from]);
        }

        showNotification("Friend request accepted!");
      }
    } catch (error) {
      console.error("Error accepting friend request:", error);
      showNotification("Failed to accept request", true);
    }
  };

  const handleReject = async (fromUserId) => {
    try {
      const response = await rejectFriendRequest(fromUserId);
      if (response.status === "Success") {
        // Update the UI by removing the rejected request
        setFriendRequests(prevRequests => 
          prevRequests.filter(request => request.from.id !== fromUserId)
        );
        showNotification("Friend request rejected");
      }
    } catch (error) {
      console.error("Error rejecting friend request:", error);
      showNotification("Failed to reject request", true);
    }
  };

  const handleRemoveFriend = async (friendId) => {
    try {
      const response = await removeFriend(friendId);
      if (response.status === "Success") {
        // Update the UI by removing the friend
        setFriends(prevFriends => 
          prevFriends.filter(friend => friend.id !== friendId)
        );
        showNotification("Friend removed");
      }
    } catch (error) {
      console.error("Error removing friend:", error);
      showNotification("Failed to remove friend", true);
    }
  };

  const handleMessage = (friendId) => {
    // Navigate to the messaging page with the selected friend
    navigate(`/messages?id=${friendId}`);
  };

  const handleViewProfile = (userId) => {
    // Navigate to the user's profile
    navigate(`/profile/${userId}`);
  };

  const showNotification = (message, isError = false) => {
    setNotification({ message, isError });
    setTimeout(() => setNotification(null), 3000);
  };

  if (loading) return <div className="friend-requests-loading">Loading...</div>;

  const renderUserTypeTag = (userType) => {
    const types = {
      "1": "Producer",
      "2": "Musician",
      "3": "Singer"
    };
    return <span className={`user-type-tag ${types[userType].toLowerCase()}`}>{types[userType]}</span>;
  };

  return (
    <div className="friend-requests-container">
      {notification && (
        <div className={`notification ${notification.isError ? 'error' : 'success'}`}>
          {notification.message}
        </div>
      )}

      <div className="tabs">
        <button 
          className={`tab ${activeTab === 'requests' ? 'active' : ''}`}
          onClick={() => setActiveTab('requests')}
        >
          Friend Requests {friendRequests.length > 0 && <span className="badge">{friendRequests.length}</span>}
        </button>
        <button 
          className={`tab ${activeTab === 'friends' ? 'active' : ''}`}
          onClick={() => setActiveTab('friends')}
        >
          Friends
        </button>
      </div>

      <div className="tab-content">
        {activeTab === 'requests' && (
          <div className="requests-list">
            <h2>Friend Requests</h2>
            {friendRequests.length === 0 ? (
              <p className="no-requests">No pending friend requests</p>
            ) : (
              friendRequests.map((request) => (
                <div key={request.from.id} className="request-card">
                  <div className="user-info">
                    <h3>{request.from.username}</h3>
                    {renderUserTypeTag(request.from.user_type)}
                    {request.from.bio && <p className="bio">{request.from.bio}</p>}
                  </div>
                  <div className="request-actions">
                    <button 
                      className="accept-button"
                      onClick={() => handleAccept(request.from.id)}
                    >
                      Accept
                    </button>
                    <button 
                      className="reject-button"
                      onClick={() => handleReject(request.from.id)}
                    >
                      Reject
                    </button>
                  </div>
                </div>
              ))
            )}
          </div>
        )}

        {activeTab === 'friends' && (
          <div className="friends-list">
            <h2>Your Friends</h2>
            {friends.length === 0 ? (
              <p className="no-friends">You don't have any friends yet</p>
            ) : (
              friends.map((friend) => (
                <div key={friend.id} className="friend-card">
                  <div className="user-info">
                    <h3>{friend.username}</h3>
                    {renderUserTypeTag(friend.user_type)}
                    {friend.bio && <p className="bio">{friend.bio}</p>}
                  </div>
                  <div className="friend-actions">
                    <button 
                      className="message-button"
                      onClick={() => handleMessage(friend.id)}
                    >
                      Message
                    </button>
                    <button 
                      className="view-profile-button"
                      onClick={() => handleViewProfile(friend.id)}
                    >
                      View Profile
                    </button>
                    <button 
                      className="reject-button"
                      onClick={() => handleRemoveFriend(friend.id)}
                    >
                      Remove
                    </button>
                  </div>
                </div>
              ))
            )}
          </div>
        )}
      </div>
    </div>
  );
};

export default FriendRequests;
